contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        address taker,
        bool isCall,
        bool isLong,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        uint256[] calldata floorAssetTokenIds
    ) public payable {
        require(maker != address(0), "maker zero");
        require(taker != address(0), "taker zero");
        require(maker != taker, "maker equals taker");
        require(duration < 10_000 days, "duration too long");
        require(block.timestamp < expiration, "order expired");
        require(strike > 0, "strike zero");
        require(premium > 0, "premium zero");
        require(floorAssetTokenIds.length == 0, "unsupported floor ids");

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: address(this),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        require(address(c).code.length > 0, "c not contract");

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeOrderHash = c.hashOppositeOrder(order);
        require(orderHash != oppositeOrderHash, "hashes equal");

        uint256 positionId;
        bool reverted;
        try c.fillOrder{value: 0}(order, "", floorAssetTokenIds) returns (uint256 id) {
            positionId = id;
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted);
        assert(positionId == uint256(oppositeOrderHash));
        assert(c.ownerOf(uint256(orderHash)) == maker);
        assert(c.ownerOf(uint256(oppositeOrderHash)) == taker);
    }

    receive() external payable {}
}

