contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        bool isCall,
        bool isLong,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public payable {
        require(expiration > 0, "bad expiration");
        require(expiration <= block.timestamp + 365 days, "expiration too far");
        require(duration > 0, "duration zero");
        require(duration <= expiration, "duration too long");

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: isCall,
            isLong: isLong,
            baseAsset: address(this),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        C.Order memory opposite = C.Order({
            maker: address(this),
            isCall: isCall,
            isLong: !isLong,
            baseAsset: address(this),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOrder(opposite);
        bytes32 returnedOppositeHash = c.hashOppositeOrder(order);

        assert(returnedOppositeHash == oppositeHash && returnedOppositeHash != orderHash);
    }

    receive() external payable {}
}

