    ) public payable {
        require(expiration > block.timestamp, "expiration must be in future");
        require(duration < 10_000 days, "duration too long");

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 orderHash = c.hashOrder(order);
        bool wasCancelled = c.cancelledOrders(orderHash);

        bool cancelReverted;
        try c.cancel(order) {
            cancelReverted = false;
        } catch {
            cancelReverted = true;
        }

