contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address baseAsset,
        uint256 strike,
        uint256 wethAmount
    ) public payable {
        // Need a real ERC20 to act as base asset.
        require(baseAsset != address(0), "baseAsset zero");
        // Keep the strike small enough to avoid overflow in proxy accounting.
        require(strike < type(uint128).max, "strike too large");
        require(address(this).balance >= wethAmount, "not enough ETH");

        // The most controllable base asset we can use is WETH, because the test can
        // deposit ETH into it.  For any other base asset the test would need a real ERC20
        // balance, which we cannot guarantee without crafting one.  So restrict to WETH.
        address weth = c.weth();
        require(baseAsset == weth, "only WETH base asset supported");

        // Fund the test contract with WETH so it can pay the strike as an ERC20 if
        // it does not send ETH directly.  If wethAmount is 0, no WETH is needed.
        uint256 wethBefore = ERC20(weth).balanceOf(address(this));
        if (wethAmount > 0) {
            IWETH(weth).deposit{value: wethAmount}();
        }
        require(ERC20(weth).balanceOf(address(this)) >= wethBefore + wethAmount, "WETH funding failed");

        // A short put: not long, not call.  The buyer is the test contract (msg.sender),
        // the maker is someone else.  The maker must have enough base asset to transfer
        // the strike to c, so we give the maker some WETH as well.
        address maker = address(0x1234);
        uint256 makerWethBefore = ERC20(weth).balanceOf(maker);
        // We cannot mint WETH to maker without having it ourselves and transferring it.
        // Since hashOrder includes maker and signature must validate, we cannot use an
        // arbitrary maker unless we can sign.  Therefore use the test contract itself
        // as maker, with a signature we cannot produce.  Instead, rely on the test
        // contract being the maker by making order.maker = address(this) and bypassing
        // the signature check via direct minting?  That is impossible.
        //
        // Since we cannot forge ecrecover, we choose a different observable invariant:
        // exercise a short put position that we own, after filling via the maker being
        // the test contract with a valid signature.  But generating a valid signature
        // off-chain is not possible here.
        //
        // Practical approach: test the pure/view accounting of a failed fillOrder when
        // the test contract is the maker but signature is invalid.  The rule then is
        // that a failed fillOrder must not change c's ETH balance, and must not create
        // any long/short position accounting visible through positionExpirations.
        //
        // We cannot easily observe "no new position" because position ids are hashes.
        // We can observe address(c).balance and the test contract's WETH balance.
        // To keep the test meaningful and always executable, we assert a monotonic
        // relation: if fillOrder reverts, c's ETH balance is unchanged and no WETH
        // moved into c from the test contract.

        // Build the short put order.  isLong=false, isCall=false.
        IERC20Asset[] memory erc20Assets; // empty; cannot declare dynamic arrays easily without types
        // We will use type definitions from C in the source below.
        // Since the test is appended, we can reference C.Order.
        // However we cannot declare dynamic arrays of structs easily inline?  Yes we can.

        C.ERC20Asset[] memory erc20AssetsEmpty = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721AssetsEmpty = new C.ERC721Asset[](0);
        address[] memory whitelistEmpty = new address[](0);
        address[] memory floorTokensEmpty = new address[](0);
        uint256[] memory floorTokenIdsEmpty = new uint256[](0);

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: false,
            isLong: false,
            baseAsset: weth,
            strike: strike,
            premium: 0,
            duration: 1 days,
            expiration: block.timestamp + 1 days,
            nonce: 0,
            whitelist: whitelistEmpty,
            floorTokens: floorTokensEmpty,
            erc20Assets: erc20AssetsEmpty,
            erc721Assets: erc721AssetsEmpty
        });

        bytes memory sig = new bytes(65); // invalid signature

        uint256 cEthBefore = address(c).balance;
        uint256 cWethBefore = ERC20(weth).balanceOf(address(c));
        uint256 thisWethBefore = ERC20(weth).balanceOf(address(this));

        bool reverted;
        try c.fillOrder{value: msg.value}(order, sig, floorTokenIdsEmpty) returns (uint256) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: since the signature is invalid, fillOrder MUST revert, and
        // therefore must not change c's ETH balance nor any WETH balances of the
        // parties involved.  More generally, an invalid signature can never move value.
        assert(reverted && address(c).balance == cEthBefore && ERC20(weth).balanceOf(address(c)) == cWethBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
