    constructor(C _c) {
        c = _c;
    }

    function run(uint256 _fee) public {
        require(_fee < 30, "fee must be less than 3%");

        uint256 balanceBefore = address(c).balance;

        c.setFee(_fee);

        assert(c.fee() == _fee && address(c).balance == balanceBefore);
    }

    receive() external payable {}
}

