contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        uint256[] calldata floorAssetTokenIds
    ) public payable {
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        require(maker == address(this), "need to cancel as maker");

        bytes32 orderHash = c.hashOrder(order);
        require(!c.cancelledOrders(orderHash), "already cancelled");

        c.cancel(order);

        require(c.cancelledOrders(orderHash), "cancel did not mark order");

        bool reverted;
        try c.fillOrder(order, "", floorAssetTokenIds) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public payable {
        require(maker == address(this), "maker must be this test");

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 orderHash = c.hashOrder(order);

        require(!c.cancelledOrders(orderHash), "precondition: order not already cancelled");

        c.cancel(order);

        require(c.cancelledOrders(orderHash), "cancel must mark order cancelled");

        bool reverted;
        try c.fillOrder(order, "", new uint256[](0)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && c.cancelledOrders(orderHash));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public payable {
        require(baseAsset != address(0), "baseAsset nonzero");
        require(expiration > block.timestamp, "expiration in future");
        require(duration < 10_000 days, "duration bounded");

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: false,
            isLong: false,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 orderHash = c.hashOrder(order);

        c.cancel(order);

        bool marked = c.cancelledOrders(orderHash);

        bool reverted;
        try c.fillOrder(order, "", new uint256[](0)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(marked && reverted);
    }
}

